window.SORULAR_96 = [{"id":1,"anaKat":"3.1. Ağ ve Sistem Güvenliği","altKat":"3.1.1. Donanım Varlıklarının Envanter Yönetimi","tedbirNo":"3.1.1.8","tedbir":"Donanım Varlıklarının Kimlik Denetimi için İstemci Sertifikalarının Kullanılması","soru":"Sertifika, yetkilendirilmiş personel tarafından güvenli bir alanda oluşturulmakta mıdır?","oneri":"Destekleyen cihazlarda, kurumun güvenli ağlarına bağlanan donanım varlıklarının kimlik denetimi için istemci sertifikaları kullanılmalıdır. Sertifika, yetkilendirilmiş personel tarafından güvenli alanda oluşturulmalıdır. Sertifikanın anahtar uzunluğu, tipi (NES/NES olmayan) ve oluşturulma yöntemi bilgi güvenliği gereksinimleri doğrultusunda seçilmelidir. Oluşturulan sertifika güvenli alanda saklanmalı ve sertifika yaşam döngüsünün takibi yapılmalıdır.","kritiklik":3},{"id":2,"anaKat":"3.1. Ağ ve Sistem Güvenliği","altKat":"3.1.1. Donanım Varlıklarının Envanter Yönetimi","tedbirNo":"3.1.1.9","tedbir":"Sabit Disk Güvenliği","soru":"Kurum tarafından temin edilen ve kullanıcı bilgisayarlarında kullanılması planlanan sabit diskleri sisteme dâhil etmek amacıyla bir süreç tanımlanmış ve uygulanmakta mıdır?","oneri":"Kurum tarafından satın alınan kullanıcı bilgisayarlarına ait sabit diskler, veri kurtarmaya imkân sağlamayacak şekilde güvenli silme işlemine tabi tutulduktan sonra sistemlere dâhil edilmelidir.","kritiklik":3},{"id":3,"anaKat":"3.1. Ağ ve Sistem Güvenliği","altKat":"3.1.2. Yazılım Varlıklarının Envanter Yönetimi","tedbirNo":"3.1.2.6","tedbir":"Yazılım ve Donanım Envanterinin Entegre Edilmesi","soru":"Yazılım envanter sistemi ve donanım envanter sistemi entegre midir?","oneri":"Yazılım ve donanım envanteri birbirleri ile entegre edilmelidir. Entegre edilen envanter merkezi olarak yönetilmelidir.","kritiklik":3},{"id":4,"anaKat":"3.1. Ağ ve Sistem Güvenliği","altKat":"3.1.2. Yazılım Varlıklarının Envanter Yönetimi","tedbirNo":"3.1.2.7","tedbir":"Beyaz Liste Yönetimi","soru":"Uygulama beyaz liste yönetimi için yazılım kullanılmakta mıdır?","oneri":"Kurum uygulama beyaz liste yönetimi yazılımı kullanmalıdır. Uygulama tarafından en az aşağıda yer alan kısıtlamalar devreye alınmalıdır.\nYalnızca onaylı yazılım kütüphanelerinin (* .dll, * .ocx, * .so vb.) yüklenmesi\nYalnızca onaylı ve dijital olarak imzalanmış betik dosyalarının (* .ps1, * .py, makrolar vb.) çalıştırılması.","kritiklik":3},{"id":5,"anaKat":"3.1. Ağ ve Sistem Güvenliği","altKat":"3.1.5. Zararlı Yazılımlardan Korunma","tedbirNo":"3.1.5.7","tedbir":"DNS Sorgularının Kayıtlarının Tutulması","soru":"Kurumda DNS sorguları kayıt edilmekte midir?","oneri":"Zararlı IP adreslerine erişimin denetlenmesi için DNS sorguları kayıt altına alınmalıdır.","kritiklik":3},{"id":6,"anaKat":"3.1. Ağ ve Sistem Güvenliği","altKat":"3.1.5. Zararlı Yazılımlardan Korunma","tedbirNo":"3.1.5.8","tedbir":"Komut Satırı Kayıtlarının Tutulması","soru":"Kurumda, PowerShell ve Bash gibi komut satırından yapılan şüpheli işlemler denetlenmekte midir?","oneri":"Kurumda, kullanıcı tarafından PowerShell ve Bash gibi komut satırı kullanılarak yapılan işlemler denetlenmeli ve merkezi olarak kayıt altına alınmalıdır.","kritiklik":3},{"id":7,"anaKat":"3.1. Ağ ve Sistem Güvenliği","altKat":"3.1.6. Ağ Güvenliği","tedbirNo":"3.1.6.30","tedbir":"Ağ Cihazlarının Yapılandırma Yönetimi","soru":"Ağ cihazları mevcut yapılandırmaları periyodik olarak kontrol edilmekte midir?","oneri":"Ağ cihazı mevcut yapılandırmaları, onaylanmış ve olması gereken güvenlik yapılandırma içerikleri ile karşılaştırılmalı ve herhangi bir uyumsuzluk tespit edildiğinde alarm üreten mekanizmalar devreye alınmalıdır.","kritiklik":3},{"id":8,"anaKat":"3.1. Ağ ve Sistem Güvenliği","altKat":"3.1.6. Ağ Güvenliği","tedbirNo":"3.1.6.31","tedbir":"Ağ Cihazlarının Yönetimi","soru":"Ağ cihazlarının yönetimi kapsamında çok faktörlü kimlik doğrulama mekanizmaları kullanılmakta mıdır?","oneri":"Ağ cihazlarının yönetimi, çok faktörlü kimlik doğrulama mekanizmaları kullanılarak şifreli ağ trafiği üzerinden yapılmalıdır. Ağ yönetimi için gerekli işlemler, bu amaç için tahsis edilen ve internet erişimi olmayan makineler üzerinden yapılmalıdır.","kritiklik":3},{"id":9,"anaKat":"3.1. Ağ ve Sistem Güvenliği","altKat":"3.1.6. Ağ Güvenliği","tedbirNo":"3.1.6.32","tedbir":"Kuruma Uzaktan Bağlanan Cihazların Yönetimi","soru":"Kuruma uzaktan bağlanacak cihazların uymaları gereken güvenlik politikaları tanımlanmakta mıdır?","oneri":"Kuruma uzaktan bağlanacak cihazların; zararlı yazılımdan korunma, işletim sistemi ve uygulama güncelliği vb. hususlar kapsamında kurum politikalarına uygunluğu güvenli uzaktan bağlantı sağlayan sistemler üzerinden (VPN vb.) kontrol edilmelidir. Kurum politikasına uymayan cihazlara bağlantı izni verilmemelidir.","kritiklik":3},{"id":10,"anaKat":"3.1. Ağ ve Sistem Güvenliği","altKat":"3.1.6. Ağ Güvenliği","tedbirNo":"3.1.6.33","tedbir":"Kripto Ağ Cihazlarının Kullanımı","soru":"Kritik ağ ortamları arasındaki iletişim için kripto ağ cihazları kullanılmakta mıdır?","oneri":"Kritik ağ ortamları arasındaki iletişim için kripto ağ cihazları kullanılmalıdır.","kritiklik":3},{"id":11,"anaKat":"3.1. Ağ ve Sistem Güvenliği","altKat":"3.1.6. Ağ Güvenliği","tedbirNo":"3.1.6.35","tedbir":"Kablosuz Çevre Birimleri Kullanımının Engellenmesi","soru":"Kritik veri işleyen kapalı ağlarda, kablosuz fare ve klavye gibi çevre birimlerinin kullanılması engellenmekte midir?","oneri":"Kritik veri işleyen, internete herhangi bir erişimi bulunmayan kapalı ağlarda kablosuz fare ve klavye gibi çevre birimlerinin kullanılması engellenmelidir.","kritiklik":3},{"id":12,"anaKat":"3.1. Ağ ve Sistem Güvenliği","altKat":"3.1.7. Veri Sızıntısı Önleme","tedbirNo":"3.1.7.9","tedbir":"Durağan Veri Güvenliğinin Sağlanması","soru":"Kritik veriyi görüntülemek ve bu veri üzerinde değişiklik yapmak için gerçekleştirilen işlemlere ait kayıtlar tutulmakta mıdır?","oneri":"Durağan veri ortamlarında yer alan kritik veri, şifrelenerek muhafaza edilmelidir. Depolanan kritik veri kimlik doğrulama mekanizması gerektiren ikincil bir araç kullanarak şifrelenmelidir. Kritik veriyi görüntülemek veya kritik veride değişiklik yapmak için gerçekleştirilen tüm işlemler kayıt altına alınmalıdır.","kritiklik":3},{"id":13,"anaKat":"3.1. Ağ ve Sistem Güvenliği","altKat":"3.1.7. Veri Sızıntısı Önleme","tedbirNo":"3.1.7.10","tedbir":"Taşınabilir Ortam Engelleme","soru":"Kritik sistemler taşınabilir ortamları desteklemeyecek şekilde yapılandırılmakta mıdır?","oneri":"Kritik sistemler taşınabilir depolama birimlerini desteklemeyecek şekilde yapılandırılmalıdır. Taşınabilir depolama birimleri takıldığında uyarı üretecek mekanizmalar aktif edilmelidir. Bu uyarılar izlenmelidir.","kritiklik":3},{"id":14,"anaKat":"3.1. Ağ ve Sistem Güvenliği","altKat":"3.1.10. Siber Güvenlik Olay Yönetimi","tedbirNo":"3.1.10.8","tedbir":"Siber Olay Yönetimi Puanlama ve Önceliklendirme","soru":"Siber olaylar, kuruma potansiyel etkileri göz önünde bulundurularak puanlanmakta ve olayların giderilmesi için hazırlanan aksiyon planında önceliklendirme risk temelli bir model kullanılarak yapılmakta mıdır?","oneri":"Olaylar, kuruma potansiyel etkileri göz önünde bulundurularak puanlanmalı ve olayların giderilmesi için hazırlanan aksiyon planında önceliklendirme için risk temelli bir model kullanılmalıdır.","kritiklik":3},{"id":15,"anaKat":"3.1. Ağ ve Sistem Güvenliği","altKat":"3.1.11. Sızma Testleri ve Güvenlik Denetimleri","tedbirNo":"3.1.11.9","tedbir":"Düzenli Kırmızı Takım Tatbikatlarının Yapılması","soru":"Kurumda düzenli aralıklarla kırmızı takım tatbikatları yapılmakta mıdır?","oneri":"Siber saldırılara karşı kurumsal hazırlığı test etmek adına düzenli kırmızı takım tatbikatları yapılmalı veya yaptırılmalıdır. Tatbikat sonuçları kurum içi dokümante edilerek raporlanmalıdır. Rapor sonuçlarına göre kurumda gerekli iyileştirmeler sağlanmalıdır.","kritiklik":3},{"id":16,"anaKat":"3.1. Ağ ve Sistem Güvenliği","altKat":"3.1.11. Sızma Testleri ve Güvenlik Denetimleri","tedbirNo":"3.1.11.10","tedbir":"Kurum Ağına Eklenen Yazılımın ve Donanımın Kontrolü","soru":"Yazılım ve donanımlar kurum ağına dâhil edilmeden önce zafiyet taraması ve güvenlik denetiminden geçmekte midir?","oneri":"Kurum ağına eklenecek donanıma veya yazılıma, ağa dâhil edilmeden önce zafiyet taraması ve güvenlik denetimi yapılmalıdır.","kritiklik":3},{"id":17,"anaKat":"3.1. Ağ ve Sistem Güvenliği","altKat":"3.1.12. Kimlik Doğrulama ve Erişim Yönetimi","tedbirNo":"3.1.12.18","tedbir":"Hesap Giriş Davranışlarında Değişikliklerin Saptanması","soru":"Kullanıcı hesap giriş davranışları düzenli olarak izlenmekte midir?","oneri":"Kullanıcı davranışları, kullanıcı rolü ve yetki seviyesi değişiklikleri güvenlik ihlal durumlarına karşı izlenmeli ve alarm mekanizmaları devreye alınmalıdır.","kritiklik":3},{"id":18,"anaKat":"3.1. Ağ ve Sistem Güvenliği","altKat":"3.1.12. Kimlik Doğrulama ve Erişim Yönetimi","tedbirNo":"3.1.12.19","tedbir":"Oturum Kayıtlarının Tutulması","soru":"Gizlilik dereceli verilerin saklandığı/işlendiği sistemler üzerinde açılan oturumlar sırasında gerçekleştirilen faaliyetler kayıt altına alınmakta mıdır?","oneri":"Gizlilik dereceli verilerin saklandığı/işlendiği sistemler üzerinde sistem yönetimi amacıyla açılan oturumlar sırasında gerçekleştirilen faaliyetler kayıt altına alınmalı ve alınan kayıtların doğrulaması yapılmalıdır.","kritiklik":3},{"id":19,"anaKat":"3.1. Ağ ve Sistem Güvenliği","altKat":"3.1.12. Kimlik Doğrulama ve Erişim Yönetimi","tedbirNo":"3.1.12.20","tedbir":"Sistem Yöneticisi Görevlerinin Güvenliği","soru":"Tüm yönetimsel görevler yönetim dışı faaliyetler için kullanılmayan belirli bilgisayarlar üzerinden mi yapılmaktadır?","oneri":"Tüm sistem yöneticisi görevleri belirli IP adresleri kullanılarak yapılmalıdır. Yönetim işlemlerini gerçekleştiren sistem yöneticileri, sadece yönetimsel haklar gerektiren işler için ilgili hesapları kullanmalıdır. Yetkilendirmelerin senede en az 1 kez olacak şekilde gözden geçirilmesi, gereksinimi kalmamış yetkilerin geri alınması sağlanmalıdır.","kritiklik":3},{"id":20,"anaKat":"3.1. Ağ ve Sistem Güvenliği","altKat":"3.1.12. Kimlik Doğrulama ve Erişim Yönetimi","tedbirNo":"3.1.12.21","tedbir":"Veri ve Parola Güvenliğinin Sağlanması","soru":"Veri ve parolaların güvenliği için otomatik parola yönetim aracı (password vault) kullanılmakta mıdır?","oneri":"Veri ve parolaların güvenliğinin sağlanması gerektiğinde otomatik parola yönetim aracı (password vault) kullanılmalıdır.","kritiklik":3},{"id":21,"anaKat":"3.1. Ağ ve Sistem Güvenliği","altKat":"3.1.13. Felaket Kurtarma ve İş Sürekliliği Yönetimi","tedbirNo":"3.1.13.17","tedbir":"Kritik Sistem Sürekliliğinin Sağlanması","soru":"Hizmetler devreye alınırken yedeklilik testleri yapılmakta mıdır?","oneri":"Kurum tarafından kritik olarak belirlenen sistem, servis, uygulama ve altyapının hizmet sürekliliğini sağlamak amacıyla gerekli yedeklilik yapıları oluşturulmalıdır. Hizmetler devreye alınırken yedeklilik testleri yapılmalıdır. Hizmet seviye taahhütleri oluşturulmalı, ölçülmeli ve raporlanmalıdır.","kritiklik":3},{"id":22,"anaKat":"3.1. Ağ ve Sistem Güvenliği","altKat":"3.1.13. Felaket Kurtarma ve İş Sürekliliği Yönetimi","tedbirNo":"3.1.13.18","tedbir":"Felaket Kurtarma Merkezi Oluşturulması","soru":"Felaket kurtarma merkezi var mıdır?","oneri":"Herhangi bir felaket anında bilgi sistemleri işlevlerinin sürdürülebilmesi için bir felaket kurtarma merkezi kurulmalıdır.","kritiklik":3},{"id":23,"anaKat":"3.1. Ağ ve Sistem Güvenliği","altKat":"3.1.14. Uzaktan Çalışma","tedbirNo":"3.1.14.18","tedbir":"Erişimin Kurum Bilgisayarları ile Sınırlandırılması","soru":"Uzaktan çalışma kapsamında kurum cihazları dışında bir erişim imkânı bulunmakta mıdır?","oneri":"Uzaktan çalışma kapsamında sadece kurum cihazları üzerinden erişim sağlanmalıdır. VPN erişiminde kurum tarafından sağlanan cihazlar için oluşturulan sertifikaların kullanılması sağlanmalıdır.","kritiklik":3},{"id":24,"anaKat":"3.1. Ağ ve Sistem Güvenliği","altKat":"3.1.14. Uzaktan Çalışma","tedbirNo":"3.1.14.19","tedbir":"Kuruma Uzaktan Bağlanan Cihazların Yönetimi","soru":"Kuruma uzaktan bağlanacak cihazların uymaları gereken güvenlik politikaları tanımlanmakta mıdır?","oneri":"Bk. Tedbir No: 3.1.6.32","kritiklik":3},{"id":25,"anaKat":"3.1. Ağ ve Sistem Güvenliği","altKat":"3.1.1. Donanım Varlıklarının Envanter Yönetimi","tedbirNo":"3.1.1.4","tedbir":"Aktif Keşif Araçlarının Kullanılması","soru":"Kurumda, ağa bağlanılan cihazları tanımak ve donanım envanterindeki değişiklikleri takip etmek amacıyla aktif keşif araçları kullanılmakta mıdır?","oneri":"Kurum ağına bağlı cihazları tanımlamak ve donanım varlık envanterindeki değişiklikleri takip etmek için aktif keşif araçları kullanılmalıdır.","kritiklik":2},{"id":26,"anaKat":"3.1. Ağ ve Sistem Güvenliği","altKat":"3.1.1. Donanım Varlıklarının Envanter Yönetimi","tedbirNo":"3.1.1.5","tedbir":"DHCP Kayıt Mekanizması ile Yeni Donanımların Tespiti","soru":"Kuruma ait DHCP sunucularında kayıt tutulmakta mıdır?","oneri":"Kurumun donanım envanterini güncel tutmak için tüm DHCP sunucularında ya da IP adres yönetim araçlarında kayıt mekanizmasının kullanımı sağlanmalıdır.","kritiklik":2},{"id":27,"anaKat":"3.1. Ağ ve Sistem Güvenliği","altKat":"3.1.1. Donanım Varlıklarının Envanter Yönetimi","tedbirNo":"3.1.1.6","tedbir":"Kullanım Ömrünü Tamamlayan Cihazların Veri Depolama Üniteleri","soru":"Kullanım ömrünü tamamlayan cihazların imha edilmesine veya tekrar kullanılmasına yönelik bir politika/prosedür tanımlanmış mıdır?","oneri":"Kullanım ömrünü tamamlayan cihazların veri depolama üniteleri (HDD, SSD, USB, disk, harici bellek vb.) güvenli bir şekilde imha edilmelidir. Kurum içinde tekrar kullanılması durumunda ise veri kurtarmaya imkân sağlamayacak şekilde güvenli silme işlemine tabi tutulduktan sonra kullanıma alınmalıdır.","kritiklik":2},{"id":28,"anaKat":"3.1. Ağ ve Sistem Güvenliği","altKat":"3.1.1. Donanım Varlıklarının Envanter Yönetimi","tedbirNo":"3.1.1.7","tedbir":"Kurum Ağı Bağlantı Noktalarında Kimlik Denetimi Yapılması","soru":"Port seviyesinde erişim kontrolü yapılmakta mıdır?","oneri":"Sadece onaylı donanımların kurum ağına bağlanabilmesi için, 802.1x standardı veya NAC çözümleri kullanılarak kurum ağına bağlanan cihazlara kimlik denetimi yapılmalıdır.","kritiklik":2},{"id":29,"anaKat":"3.2. Uygulama ve Veri Güvenliği","altKat":"3.2.1. Kimlik Doğrulama","tedbirNo":"3.2.1.13","tedbir":"Merkezi Kimlik Doğrulama Mekanizmalarının Kullanılması","soru":"Merkezi kimlik yönetim ve doğrulama sistemi kullanılıyor mu?","oneri":"Kurumsal merkezi kimlik yönetim ve doğrulama sistemleri kullanılmalı veya e-Devlet sistemi ile entegrasyon sağlanmalıdır.","kritiklik":3},{"id":30,"anaKat":"3.2. Uygulama ve Veri Güvenliği","altKat":"3.2.2. Oturum Yönetimi","tedbirNo":"3.2.2.5","tedbir":"Kullanıcıların Aktif Oturumlarını Yönetebilmesi","soru":"Uygulama arayüzleri kullanılarak etkin olan oturumlar listelenebiliyor mu?","oneri":"Kullanıcılar uygulamadaki etkin oturumlarını görüntüleyebilmeli ve aktif oturumlarından istediğini sonlandırabilmelidir.","kritiklik":3},{"id":31,"anaKat":"3.2. Uygulama ve Veri Güvenliği","altKat":"3.2.3. Yetkilendirme","tedbirNo":"3.2.3.4","tedbir":"İçerik Duyarlı ve Gelişmiş Erişim Denetimi","soru":"Uygulamada yetkilendirmeler zaman, konum, kullanılan ağ, IP adresi gibi özelliklere göre sınırlandırılabiliyor mu?","oneri":"Uygulama içerik duyarlı (zaman, konum, IP adresi gibi öznitelikler) erişim denetimi yapabilmelidir. Uygulama; fonksiyonlara, kaynaklara, veriye erişim sürelerini, kullanım oranlarını veya kullanım sıklığını sınırlandırabilmelidir.","kritiklik":3},{"id":32,"anaKat":"3.2. Uygulama ve Veri Güvenliği","altKat":"3.2.7. Veri Tabanı ve Kayıt Yönetimi","tedbirNo":"3.2.7.18","tedbir":"Tüm Kullanıcı İşlemlerinin Kaydedilmesi","soru":"Veri tabanı denetleme mekanizması aktif mi?","oneri":"Veri tabanı üzerinde bulunan tüm kullanıcılar tarafından gerçekleştirilen işlemler için denetim kayıtları oluşturulmalıdır. Bu kapsamda ilgili denetim politikaları/prosedürleri kurum ihtiyaçları doğrultusunda belirlenerek veri tabanı üzerinde uygulanmalıdır.","kritiklik":3},{"id":33,"anaKat":"3.2. Uygulama ve Veri Güvenliği","altKat":"3.2.7. Veri Tabanı ve Kayıt Yönetimi","tedbirNo":"3.2.7.19","tedbir":"Saklama Gereksinimi Sona Eren Kritik Verinin Güvenli Silinmesi","soru":"Kritik verinin kullanımları tamamlandığında üzerlerinde ne gibi işlemlerin uygulanacağı tanımlanmış mıdır?","oneri":"Saklama gereksinimi sona eren kritik veri geri getirilemeyecek şekilde silinmelidir.","kritiklik":3},{"id":34,"anaKat":"3.2. Uygulama ve Veri Güvenliği","altKat":"3.2.7. Veri Tabanı ve Kayıt Yönetimi","tedbirNo":"3.2.7.20","tedbir":"İşlenmesi Asıl Amaç Olmayan Verilerin Veri Tabanı Sunucusundan Maskelenerek Sunulması","soru":"Veri tabanı üzerinde bulunan ilgili veriler, işlenmesi asıl amaç olmadığında kullanıcı yetkisi doğrultusunda maskelenerek sunulmakta mıdır?","oneri":"İşlenmesi asıl amaç olmadığı durumlarda maskelenmesine ihtiyaç duyulan veriler dokümante edilerek belirlenmelidir. Bu kapsamda dokümante edilmiş ilgili veriler, işlenmesi asıl amaç olmadığında kullanıcının yetkisi doğrultusunda veri tabanı sunucusundan maskelenerek sunulmalıdır.","kritiklik":3},{"id":35,"anaKat":"3.2. Uygulama ve Veri Güvenliği","altKat":"3.2.7. Veri Tabanı ve Kayıt Yönetimi","tedbirNo":"3.2.7.21","tedbir":"Veri Tabanına Gönderilen Sorguların Kontrol Edilmesi","soru":"Veri tabanına gönderilen tüm sorgular için uygulamadan bağımsız olarak içerik ve yazım denetimi yapılmakta mıdır?","oneri":"Veri tabanına gönderilen tüm sorgular içerik ve yazım açısından denetlenmeli, olası enjeksiyon saldırıları engellenmelidir.","kritiklik":3},{"id":36,"anaKat":"3.2. Uygulama ve Veri Güvenliği","altKat":"3.2.9. İletişim Güvenliği","tedbirNo":"3.2.9.4","tedbir":"Hatalı Sertifikaların Tespiti","soru":"Uygulama adına oluşturulabilecek hatalı sertifikalar için sertifika şeffaflığı logları (Certificate Transparency Logs) üzerinde düzenli olarak kontroller yapılıyor mu?","oneri":"Uygulama adına oluşturulabilecek hatalı sertifikalar için sertifika şeffaflığı logları (Certificate Transparency Logs) üzerinde düzenli olarak kontroller yapılmalıdır.","kritiklik":3},{"id":37,"anaKat":"3.2. Uygulama ve Veri Güvenliği","altKat":"3.2.9. İletişim Güvenliği","tedbirNo":"3.2.9.5","tedbir":"SSL/TLS Hata İz Kayıtları","soru":"SSL/TLS bağlantı hatası durumlarında iz kaydı oluşturuluyor mu?","oneri":"SSL/TLS bağlantı hatası durumları için iz kaydı oluşturulmalıdır.","kritiklik":3},{"id":38,"anaKat":"3.2. Uygulama ve Veri Güvenliği","altKat":"3.2.9. İletişim Güvenliği","tedbirNo":"3.2.9.7","tedbir":"Kurum Tarafından Onaylanmış Sertifikaların Kullanılması","soru":"Kurum tarafından yetkilendirilmiş sertifika otoriteleri/üreticileri belirlenmiş ve dokümante edilmiş midir?","oneri":"Yazılımlarda kullanılmak üzere üretilmiş sertifikaların kaynağı kontrol edilmelidir. Yazılımlarda sadece kurum tarafından belirlenen kaynak/otorite tarafından üretilmiş sertifikaların kullanılması sağlanmalıdır.","kritiklik":3},{"id":39,"anaKat":"3.2. Uygulama ve Veri Güvenliği","altKat":"3.2.10. Kötücül İşlemleri Engelleme","tedbirNo":"3.2.10.15","tedbir":"TS ISO/IEC 19790-24759 OnaylıKriptografik Modüllerin ve Rastgele Sayı Üreteçlerinin Kullanılması","soru":"Kullanılan kriptografik modüller/rastgele sayı üreteçleri TS ISO/IEC 19790-24759 onaylı mıdır?","oneri":"Uygulamada şifreleme, anahtar değişimi, dijital imzalama veya özet alma gibi fonksiyonlar bulunuyorsa TS ISO/IEC 19790-24759 onaylı kriptografik modüller ve rastgele sayı üreteçleri kullanılmalıdır.","kritiklik":3},{"id":40,"anaKat":"3.2. Uygulama ve Veri Güvenliği","altKat":"3.2.10. Kötücül İşlemleri Engelleme","tedbirNo":"3.2.10.16","tedbir":"Karakter Kodlamasının Tespiti","soru":"Girdi-çıktı denetimi yapılmadan önce gerçekleştirilecek faaliyetler tasarım dokümanında tanımlanmakta mıdır?","oneri":"Girdi-çıktı denetimi yapılmadan önce veri üzerinde karakter kodlaması (character encoding) yapılıp yapılmadığı tespit edilmelidir. Tespit edilen kodlamaya göre denetimler gerçekleştirilmelidir.","kritiklik":3},{"id":41,"anaKat":"3.2. Uygulama ve Veri Güvenliği","altKat":"3.2.11. Dış Sistem Entegrasyonlarının Güvenliği","tedbirNo":"3.2.11.9","tedbir":"Dış Sistemler / Uygulamalar Arası Çağrıların Kayıt Altına Alınması","soru":"Dış sistemler / uygulamalar arası çağrılar kayıt altına alınıyor mu?","oneri":"Dış sistemler ve uygulamalar arasındaki çağrıların girdi parametreleri ve sonuçları çağrıyı yapan ve sunan uygulamalar tarafından kayıt altına alınmalıdır.","kritiklik":3},{"id":42,"anaKat":"3.2. Uygulama ve Veri Güvenliği","altKat":"3.2.1. Kimlik Doğrulama","tedbirNo":"3.2.1.10","tedbir":"Güçlü Kimlik Doğrulama Yöntemlerinin Desteklenmesi","soru":"Kimlik doğrulama mekanizmalarında elektronik imza gibi güçlü yöntemlerin kullanılabilmesi için seçenek sağlanıyor mu?","oneri":"Unutulan parolanın sıfırlaması kullanıcı adının unutulması vb. durumlar için; kısa ileti, e-posta onayı, mobil onay, çevrimdışı onay vb. yöntemler kullanılmalıdır. İlgili yöntemler kullanılırken sahip olunan, bilinen ve biyometrik faktörlerin en az ikisinden yararlanılmalıdır. Hassas işlevler gerçekleştirilmeden önce, yeniden kimlik doğrulama, daha güçlü bir mekanizmayla kimlik doğrulama, çok faktörlü kimlik doğrulama veya işlem imzalama gibi yöntemler uygulanmalıdır. Uygulamanın ilgili yönetim arayüzlerine yalnızca yetkili kullanıcılar tarafından erişim sağlanmalıdır. Açık anahtar altyapısı tabanlı kimlik doğrulama kullanılıyorsa sertifika yolu doğrulanmalı ve kullanıcının sertifikası sistem üzerindeki geçerli kullanıcı veya grup bilgisi ile eşleştirilmelidir.","kritiklik":2},{"id":43,"anaKat":"3.2. Uygulama ve Veri Güvenliği","altKat":"3.2.1. Kimlik Doğrulama","tedbirNo":"3.2.1.11","tedbir":"Hesap Kurtarma Seçeneklerinin Güvenliği","soru":"Uygulama kullanıcı bilgilerinin değişmesi ile sonuçlanacak tüm durumlar için iz kaydı oluşturmakta mıdır?","oneri":"Hesaba yeniden erişebilecek tüm hesap kimlik doğrulama işlevleri (parola güncelleme, parolamı unuttum, devre dışı/kayıp simge (token), süresi dolmuş parolanın güncellenmesi, yardım masası vb.) en az ana kimlik doğrulama mekanizması kadar güvenli olmalıdır.","kritiklik":2},{"id":44,"anaKat":"3.2. Uygulama ve Veri Güvenliği","altKat":"3.2.1. Kimlik Doğrulama","tedbirNo":"3.2.1.12","tedbir":"Kullanılmayan Hesapların Tespiti","soru":"Uygulama, belirli bir süre boyunca hiç kullanılmamış olan hesapları raporlayabilmekte midir?","oneri":"Uygulama, belirli bir süre boyunca hiç kullanılmamış olan hesapları raporlayabilmelidir. Bu hesaplar pasif duruma getirilmeli veya silinmelidir.","kritiklik":2},{"id":45,"anaKat":"3.2. Uygulama ve Veri Güvenliği","altKat":"3.2.4. Dosyaların ve Kaynakların Güvenliği","tedbirNo":"3.2.4.7","tedbir":"Açık Kaynak Kod Tabanının Kurum Bünyesinde Tutulması","soru":"Açık kaynaklı kod kullanarak yazılım geliştirilirken kod tabanı geliştirme yapan kurum bünyesinde tutuluyor mu?","oneri":"Açık kaynak kod tabanın zafiyete neden olacak şekilde değiştirilmesini engellemek için kod tabanı kurum bünyesinde barındırılmalıdır.","kritiklik":2},{"id":46,"anaKat":"3.6. Fiziksel Mekânların Güvenliği","altKat":"3.6.1. Genel Güvenlik Tedbirleri","tedbirNo":"3.6.1.13","tedbir":"Ziyaretçi Fiziksel Erişim Güvenliği","soru":"Kurum bünyesinde işletilen bir ziyaretçi kabul prosedürü bulunmakta mıdır?","oneri":"Ziyaretçi giriş ve çıkışı refakatçi ile sağlanmalıdır. Ziyaretçi giriş kartı yalnızca ilgili alanlara erişim sağlayacak şekilde tanımlanmalıdır. Ziyaretçilerin tesis içerisinde refakatçi personel olmadan dolaşmasına izin verilmemelidir. Ziyaretçilerin giriş ve çıkışlarda üstleri ve eşyaları uygun yöntemlerle (elle arama, x-ray vb.) aranmalıdır. Ziyaretçilerin bilgisayar, cep telefonu, akıllı saat vb. elektronik cihazları istisnai izne tabi olmalıdır. Bu cihazların kurum içerisine alınmasına izin verilmeden önce, güvenlik birimi tarafından kuruma girişi yapılacak cihazın seri numarası, marka, modeli ve hangi amaçla kullanılacağı bilgileri kayıt altına alınmalıdır.","kritiklik":3},{"id":47,"anaKat":"3.6. Fiziksel Mekânların Güvenliği","altKat":"3.6.1. Genel Güvenlik Tedbirleri","tedbirNo":"3.6.1.14","tedbir":"Fiziksel Erişim Güvenliği","soru":"Emniyet ve güvenlik açısından önem taşıyan yerlere girişte yeterli seviyede güvenlik kontrolleri uygulanmakta mıdır?","oneri":"Personelin hangi bölgelere erişebileceği konusunda bir tanımlama yapılmalıdır. Emniyet ve güvenlik açısından önem taşıyan yerlere girişte güvenlik birimine ek güvenlik önlemlerinin olması (kartlı giriş sistemi, biyometrik veriler ile kimlik doğrulama sistemi vb.) sağlanmalıdır.","kritiklik":3},{"id":48,"anaKat":"3.6. Fiziksel Mekânların Güvenliği","altKat":"3.6.2. Sistem Odası/Veri Merkezine Yönelik Güvenlik Tedbirleri","tedbirNo":"3.6.2.15","tedbir":"İklimlendirme Kontrolü","soru":"Sistem odası/veri merkezinde kullanılan klimalar yedekli midir?","oneri":"Sistem odası/veri merkezinde yedekli olacak şekilde hassas kontrollü klima bulunmalıdır. Klimalardan bir tanesi bekleme konumunda çalışmalı ve diğer klima herhangi bir sebepten devre dışı kaldığında ya da gerekli soğutmayı yapamadığında bekleme konumundaki klima otomatik olarak devreye girmelidir. Hassas kontrollü klimalar sistem odası/veri merkezi kapasitesine uygun olarak seçilmeli, tam otomatik elektronik kontrollü olmalıdır. Arızalara yönelik alarm üretebilmeli, enerjinin herhangi bir anda kesilip gelmesiyle otomatik olarak devreye girebilmelidir. Klimaların periyodik bakım, ölçüm ve test işlemleri gerçekleştirilmeli ve kayıt altına alınmalıdır.","kritiklik":3},{"id":49,"anaKat":"3.6. Fiziksel Mekânların Güvenliği","altKat":"3.6.3. Elektromanyetik Bilgi Kaçaklarından Korunma Yöntemleri (TEMPEST)","tedbirNo":"3.6.3.3","tedbir":"TEMPEST Tesisat Kurallarına Uyum","soru":"Sistem odası/veri merkezindeki cihazların bulunduğu odalarda/bölümlerde elektromanyetik bilgi kaçaklarına karşı TEMPEST tesisat kurallarına uygun önlemler alınmakta mıdır?","oneri":"Sistem odası/veri merkezindeki cihazların bulunduğu odalarda/bölümlerde elektromanyetik bilgi kaçaklarına karşı TEMPEST tesisat kurallarına/ilgili mevzuatlara uygun önlemler alınmalıdır.","kritiklik":3},{"id":50,"anaKat":"3.6. Fiziksel Mekânların Güvenliği","altKat":"3.6.1. Genel Güvenlik Tedbirleri","tedbirNo":"3.6.1.10","tedbir":"Çalışma Alanlarının Güvenliği","soru":"Binalarda ziyaretçilerin kabul edileceği lobi ve toplantı odaları, personelin çalışma alanlarından ayrı ve fiziksel erişimin kontrollü olduğu bir bölgede midir?","oneri":"Binalarda ziyaretçilerin kabul edileceği lobi ve toplantı odaları, personelin çalışma alanlarından ayrı bir bölgede olmalıdır. İki bölge arasındaki geçiş kontrollü olarak sağlanmalıdır. Kritik veri, doküman ve belgelerin bulunduğu ve/veya görüşmelerin gerçekleştirildiği çalışma odalarında/ortamlarında mobil cihazlar ve veri transferi özelliğine sahip cihazlar bulundurulmamalıdır.","kritiklik":2},{"id":51,"anaKat":"3.6. Fiziksel Mekânların Güvenliği","altKat":"3.6.1. Genel Güvenlik Tedbirleri","tedbirNo":"3.6.1.11","tedbir":"Destekleyici Altyapı Hizmetleri","soru":"Bakım kayıtları tutulmakta mıdır?","oneri":"Çalışma alanlarına gelen elektrik enerji hattı yedekli olmalıdır. Jeneratör ve UPS sistemleri bulunmalı, yedekliliği sağlanmalı ve düzenli bakımı (akülerin kontrolü, yeterli mazot bulundurma vb.) yapılmalıdır. Jeneratör ve UPS bakımı, onarımı ve testi için yapılan tüm işlemler kayıt altına alınmalıdır.","kritiklik":2},{"id":52,"anaKat":"5.1. İşletim Sistemi Sıkılaştırma Tedbirleri","altKat":"5.1.1. Genel Sıkılaştırma Tedbirleri","tedbirNo":"5.1.1.19","tedbir":"Sunucularda Çalışan Servislerin Takibi","soru":"Sunucularda gerekli ve gereksiz servisler belirlenmiş midir?","oneri":"Sunucuların normal işleyişi için gerekli olan servisler dışında başka bir servisin sunucuda açılması halinde alarm üretilmeli ve ilgili servis kapatılmalıdır.","kritiklik":3},{"id":53,"anaKat":"5.1. İşletim Sistemi Sıkılaştırma Tedbirleri","altKat":"5.1.1. Genel Sıkılaştırma Tedbirleri","tedbirNo":"5.1.1.20","tedbir":"Bilgisayar Tabanlı Saldırı Tespit ve Engelleme Sistemlerinin Kullanılması","soru":"Sistem yerelinde saldırı tespit ve engelleme sistemi (HIDS/HIPS) kullanılmakta mıdır?","oneri":"Makine özelinde saldırı tespit ve engelleme sistemi (HIDS/HIPS) kullanılmalıdır.","kritiklik":3},{"id":54,"anaKat":"5.1. İşletim Sistemi Sıkılaştırma Tedbirleri","altKat":"5.1.1. Genel Sıkılaştırma Tedbirleri","tedbirNo":"5.1.1.21","tedbir":"Disk Kotalarının Belirlenmesi","soru":"Kullanıcılar için disk kotaları belirlenmiş midir?","oneri":"Tüm makinelerde kullanıcılar için her dosya sistemine özel disk kota politikaları belirlenmeli ve etkinleştirilmelidir.","kritiklik":3},{"id":55,"anaKat":"5.1. İşletim Sistemi Sıkılaştırma Tedbirleri","altKat":"5.1.1. Genel Sıkılaştırma Tedbirleri","tedbirNo":"5.1.1.22","tedbir":"Disk Seviyesinde Şifreleme Yapılması","soru":"Kritik bilgi içeren ve/veya işleyen makineler için disk seviyesinde şifreleme yapılmakta mıdır?","oneri":"Kritik bilgi içeren ve/veya işleyen makinelerde disk seviyesinde şifreleme yapılmalıdır.","kritiklik":3},{"id":56,"anaKat":"5.1. İşletim Sistemi Sıkılaştırma Tedbirleri","altKat":"5.1.1. Genel Sıkılaştırma Tedbirleri","tedbirNo":"5.1.1.13","tedbir":"Kullanılmayan Uygulamaların Kaldırılması","soru":"Sistemde kullanılmayan uygulamalar sistemlerden kaldırılmış mıdır?","oneri":"Sistemlerde kullanılmayan uygulamalar belirlenerek kaldırılmalıdır.","kritiklik":2},{"id":57,"anaKat":"5.1. İşletim Sistemi Sıkılaştırma Tedbirleri","altKat":"5.1.1. Genel Sıkılaştırma Tedbirleri","tedbirNo":"5.1.1.14","tedbir":"Merkezi Güncelleme Sunucusu","soru":"Güncelleştirme işlemleri için merkezi bir güncelleştirme sunucusu kullanılmakta mıdır?","oneri":"İşletim sistemi güncellemeleri için merkezi bir güncelleme sunucusu oluşturulmalıdır.","kritiklik":2},{"id":58,"anaKat":"4.1. Kişisel Verilerin Güvenliği","altKat":"4.1.2. Erişim Kayıtları Yönetimi","tedbirNo":"4.1.2.6","tedbir":"Erişim Kayıtlarında Özel Nitelikli Kişisel Veri Bulundurulmaması","soru":"Erişim kayıtları özel nitelikli kişisel veri barındırıyor mu?","oneri":"Erişim kayıtları özel nitelikli kişisel veri barındırmamalıdır. Kayıtlarda özel nitelikli kişisel verinin bulundurulmasının zorunlu olduğu durumlarda, işlem detayının anlaşılabileceği şekilde kişisel verilerin güvenliği maskeleme vb. yöntemler ile sağlanmalıdır. Bk. Tedbir No: 3.2.8.3","kritiklik":3},{"id":59,"anaKat":"4.1. Kişisel Verilerin Güvenliği","altKat":"4.1.3. Yetkilendirme","tedbirNo":"4.1.3.7","tedbir":"Alt Bileşenler Arasında Veri Akışı için Erişimlerin Doğrulanması","soru":"Sistem içi kişisel verinin akışı için erişim doğrulama kontrolü yapılmakta mıdır?","oneri":"Sistem içi kişisel verinin akışı için erişim doğrulama kontrolü yapılmalıdır.","kritiklik":3},{"id":60,"anaKat":"4.1. Kişisel Verilerin Güvenliği","altKat":"4.1.7. Açık Rıza Yönetimi","tedbirNo":"4.1.7.4","tedbir":"Uygulama Üzerinden Açık Rıza Alınması","soru":"Uygulama üzerinden açık rızanın alınması ve açık rıza beyan durumunun sorgulanması için bir mekanizma/süreç işletilmekte midir?","oneri":"Özel nitelikli kişisel verinin işlenmesi ve kişisel verinin üçüncü kişilere aktarılması durumunda açık rıza uygulama üzerinden alınmalı ve açık rıza beyan durumu sorgulanabilmelidir.","kritiklik":3},{"id":61,"anaKat":"4.1. Kişisel Verilerin Güvenliği","altKat":"4.1.7. Açık Rıza Yönetimi","tedbirNo":"4.1.7.5","tedbir":"Açık Rıza Metninin Güncellenmesi","soru":"Uygulama üzerinde açık rıza metninin güncellenebilmesi için bir mekanizma/süreç tanımlanmış mıdır?","oneri":"Uygulama üzerinde açık rıza metni yetkili kişiler tarafından güncellenebilmelidir. Güncelleme öncesindeki açık rıza metinleri saklanmalıdır. Güncellenen açık rıza metinleri için kullanıcılardan tekrar açık rıza alınması sağlanmalıdır.","kritiklik":3},{"id":62,"anaKat":"4.1. Kişisel Verilerin Güvenliği","altKat":"4.1.7. Açık Rıza Yönetimi","tedbirNo":"4.1.7.6","tedbir":"Açık Rıza ile İlgili Taleplerin Yönetilmesi","soru":"Uygulama üzerinden açık rıza ile ilgili taleplerin yönetimi sağlanabilmekte midir?","oneri":"İlgili kişi, açık rızasını geri alma talebini uygulama üzerinden gerçekleştirebilmelidir. İlgili kişinin açık rızasını geri alma talebi veri sorumlusu tarafından uygulanmalı ve ilgili kişinin açık rızasına dayanarak yapılan veri işleme faaliyetleri durdurulmalıdır.","kritiklik":3},{"id":63,"anaKat":"4.1. Kişisel Verilerin Güvenliği","altKat":"4.1.7. Açık Rıza Yönetimi","tedbirNo":"4.1.7.7","tedbir":"Islak İmzalı Açık Rıza Metninin Saklanması","soru":"Islak imzalı açık rıza metinlerinin taranmış halinin saklanması amacıyla bir süreç işletilmekte midir?","oneri":"İlgili kişiden alınmış ıslak imzalı (fiziksel) açık rıza metninin aslı ya da taranmış kopyası saklanmalıdır.","kritiklik":3},{"id":64,"anaKat":"5.3. Sunucu Sıkılaştırma Tedbirleri","altKat":"5.3.2. Sanallaştırma Sunucusu Sıkılaştırma Tedbirleri","tedbirNo":"5.3.2.15","tedbir":"Disk ve İmajların Şifreli Olarak Saklanması","soru":"Sanal makinelere ait diskler şifreli olarak korunmakta mıdır?","oneri":"Sanal makineye ait imajlar ve anlık görüntüler şifreli olarak muhafaza edilmelidir. Ayrıca, sanal makinelerde disk seviyesinde şifreleme yapılmalıdır.","kritiklik":3},{"id":65,"anaKat":"5.3. Sunucu Sıkılaştırma Tedbirleri","altKat":"5.3.1. Web Sunucusu Sıkılaştırma Tedbirleri","tedbirNo":"5.3.1.19","tedbir":"İz Kayıtlarının Merkezi Kayıt Sistemine Gönderilmesi","soru":"Web sunucularından alınan iz kayıtları merkezi bir kayıt sistemine gönderiliyor mudur?","oneri":"Web sunucularından alınan iz kayıtları merkezi bir kayıt sistemine gönderilmelidir. Bk. Tedbir No: 3.1.8.6","kritiklik":2},{"id":66,"anaKat":"5.3. Sunucu Sıkılaştırma Tedbirleri","altKat":"5.3.1. Web Sunucusu Sıkılaştırma Tedbirleri","tedbirNo":"5.3.1.20","tedbir":"Sunucuya IP Adresi Üzerinden Erişimlerin Engellenmesi","soru":"Sunucuya IP adresi üzerinden erişimler engellenmiş midir?","oneri":"Sunucuya IP adresi üzerinden yapılan erişimler engellenmelidir.","kritiklik":2},{"id":67,"anaKat":"5.3. Sunucu Sıkılaştırma Tedbirleri","altKat":"5.3.2. Sanallaştırma Sunucusu Sıkılaştırma Tedbirleri","tedbirNo":"5.3.2.10","tedbir":"Sanallaştırma Yazılımının Merkezi Olarak Güncellenmesi","soru":"Sanallaştırma yazılımı merkezi olarak güncellenmekte midir?","oneri":"Sanallaştırma yazılımı çalıştığı tüm sunucularda merkezi olarak eş zamanlı güncellenmelidir.","kritiklik":2},{"id":68,"anaKat":"4.4. Kripto Uygulamaları Güvenliği","altKat":"4.4.1. Kriptografik Algoritmalar ve Kullanımı","tedbirNo":"4.4.1.4","tedbir":"Milli Kriptografik Algoritmaların Gerçeklendiği Kripto Cihazlarının Tedariki","soru":"Milli kriptografik algoritmalar, milli üreticilerden tedarik edilen cihazlarda mı gerçeklenmiştir?","oneri":"Kritik bilgi/veri işleyen kurumların, kritiklik seviyesine uygun tipte milli kriptografik algoritmaların gerçeklendiği cihazlar temin edilmelidir. Yetkili kripto analiz laboratuvarından güvenli şekilde kullanılabileceğine dair kripto analiz raporu bulunan milli kriptografik algoritmaların donanımsal olarak gerçeklendiği bu kripto cihazların, yetkili laboratuvar tarafından yapılan COMSEC güvenlik testlerinden başarılı bir şekilde geçmiş olmaları gerekmektedir. COMSEC güvenlik testlerine tabi tutulan kripto modüller için Ortak Kriter ve/veya TS ISO/EC 19790 – 24759 standardına uyum gerekliliği bulunmamaktadır.","kritiklik":3},{"id":69,"anaKat":"4.4. Kripto Uygulamaları Güvenliği","altKat":"4.4.2. Şifreleme ve Anahtar Yönetimi","tedbirNo":"4.4.2.20","tedbir":"Anahtar Taşıma Cihazlarında Yapılan Tüm Anahtar İşlemlerinin Kaydının Tutulması","soru":"Anahtar taşıma cihazlarında yetkili kullanıcının yaptığı tüm işlemler kayıt altına alınmakta mıdır?","oneri":"Anahtar taşıma cihazlarında yalnızca anahtar alma ve yayımlama yetkisi olan personel işlem yapabilmelidir. Yapılan tüm işlemler anahtar bilgisi ve işlemi gerçekleştiren kullanıcı ile birlikte kayıt altına alınmalıdır. Kayıtlar uygun şekilde korunmalıdır.","kritiklik":3},{"id":70,"anaKat":"4.4. Kripto Uygulamaları Güvenliği","altKat":"4.4.2. Şifreleme ve Anahtar Yönetimi","tedbirNo":"4.4.2.21","tedbir":"Anahtar Taşıma Cihazlarında Bulunan Anahtarın Onaylı Kriptografik Yöntemlerle Şifreli Olarak Tutulması","soru":"Anahtar taşıma cihazlarında bulunan anahtarlar onaylı kriptografik yöntemlerle şifreli olarak tutulmakta mıdır?","oneri":"Anahtar taşıma cihazlarında bulunan anahtarlar bellek gölgesinde öznitelikleri listelenerek ulaşılacak şekilde, onaylı kriptografik yöntemlerle şifreli olarak tutulmalıdır ve sadece yüklenirken açılmalıdır.","kritiklik":3},{"id":71,"anaKat":"4.4. Kripto Uygulamaları Güvenliği","altKat":"4.4.2. Şifreleme ve Anahtar Yönetimi","tedbirNo":"4.4.2.23","tedbir":"Kripto Güvenlik Belgesi Kontrolü","soru":"Kriptografik anahtarlara erişim yetkisi verilecek personel için kripto güvenlik belgesi kontrolü yapılmakta mıdır?","oneri":"Kriptografik anahtarlara erişim sadece yetki sahibi kleranslı (kripto güvenlik belgesi) personel ile sınırlanlandırılmalıdır.","kritiklik":3},{"id":72,"anaKat":"4.4. Kripto Uygulamaları Güvenliği","altKat":"4.4.2. Şifreleme ve Anahtar Yönetimi","tedbirNo":"4.4.2.24","tedbir":"Anahtar Kimliği","soru":"Anahtarlar tekil olarak adreslenmekte ve yaşam çevrim aşamaları takip edilmekte midir?","oneri":"Anahtarlar mümkünse tekil olarak adreslenebilir olmalıdır. Örneğin, anahtarların üzerinde veya yanlarında kimlik bilgisi bulunmalıdır. Anahtarın kimliği kullanılarak, alınan kayıtlar üzerinden anahtarın geçmişine ulaşılabilmelidir.","kritiklik":3},{"id":73,"anaKat":"3.3. Taşınabilir Cihaz ve Ortam Güvenliği","altKat":"3.3.1. Akıllı Telefon ve Tablet Güvenliği","tedbirNo":"3.3.1.8","tedbir":"Güvenlik Yazılımlarının Yüklenmesi","soru":"Zararlı yazılımları tespit eden ve önleyen uygulamalar kullanılmakta mıdır?","oneri":"Zararlı yazılımları tespit eden ve önleyen güvenlik uygulamaları kullanılmalıdır.","kritiklik":3},{"id":74,"anaKat":"3.3. Taşınabilir Cihaz ve Ortam Güvenliği","altKat":"3.3.1. Akıllı Telefon ve Tablet Güvenliği","tedbirNo":"3.3.1.9","tedbir":"Taşınabilir Cihaz Yönetimi","soru":"Kurum kritik veriye erişen cihazlarını merkezi olarak yönetebilmekte midir?","oneri":"Kritik veriye erişen kişisel ve kurumsal cihazlar uzaktan yönetilebilmeli, cihazlara güvenlik politikaları uygulanabilmeli ve gerek duyulduğunda politikalar uzaktan güncellenebilmelidir.","kritiklik":3},{"id":75,"anaKat":"3.3. Taşınabilir Cihaz ve Ortam Güvenliği","altKat":"3.3.1. Akıllı Telefon ve Tablet Güvenliği","tedbirNo":"3.3.1.10","tedbir":"Taşınabilir Cihazların Ayrı Sistemlerde Kullanılması","soru":"Kritik seviyeli ağlarda kullanılan taşınabilir cihazlar kurum dışı veya internete bağlı ağlarda kullanılmakta mıdır?","oneri":"Kritik seviyeli ağlarda kullanılan taşınabilir cihazlar, internete bağlı veya kurum dışı sistemlerde kullanılmamalıdır.","kritiklik":3},{"id":76,"anaKat":"3.3. Taşınabilir Cihaz ve Ortam Güvenliği","altKat":"3.3.1. Akıllı Telefon ve Tablet Güvenliği","tedbirNo":"3.3.1.11","tedbir":"Parola Politikaları","soru":"Kurumun güvenlik ihtiyaçlarına göre bir mobil cihaz parola politikası belirlenmiş midir?","oneri":"Taşınabilir cihazlar için parola politikaları belirlenmeli ve ekran kilitleri için bu politikanın uygulanması zorunlu tutulmalıdır.","kritiklik":3},{"id":77,"anaKat":"3.4. Nesnelerin İnterneti (IoT) Cihazlarının Güvenliği","altKat":"3.4.1. Ağ Servisleri ve İletişimi","tedbirNo":"3.4.1.9","tedbir":"Ağ Üzerinden Gönderilen Verinin Şifrelenmesi","soru":"Cihazlardan gönderilen kritik veri şifreli gönderilmekte midir?","oneri":"Cihazın ağ üzerinden veri gönderimi sırasında, kritik veri cihazın desteklediği şifreleme algoritmalarıyla şifrelenmelidir.","kritiklik":3},{"id":78,"anaKat":"3.4. Nesnelerin İnterneti (IoT) Cihazlarının Güvenliği","altKat":"3.4.2. Dâhili Veri Depolama","tedbirNo":"3.4.2.3","tedbir":"Kullanılan Cihazlardan Kritik Verinin Temizlenmesi","soru":"Kritik verilerin cihazlardan geri döndürülemeyecek şekilde silinmesi amacıyla bir prosedür belirlenmiş ve uygulanmakta mıdır?","oneri":"Bilgi güvenliği gereksinimleri göz önünde bulundurularak, kullanımına ihtiyaç kalmayan veya farklı alanlarda kullanılacak cihazlar üzerindeki kritik veri geri döndürülemeyecek şekilde silinmelidir. Kritik verinin cihaz üzerinden güvenli silinmesinin mümkün olmadığı durumlarda cihaz ulusal/uluslararası kabul görmüş yöntemlere uygun şekilde imha edilmelidir. Bk. Tedbir No: 3.4.1.4","kritiklik":3},{"id":79,"anaKat":"3.4. Nesnelerin İnterneti (IoT) Cihazlarının Güvenliği","altKat":"3.4.5. Diğer Güvenlik Tedbirleri","tedbirNo":"3.4.5.3","tedbir":"Gömülü İşletim Sistemi İçin Kod Analiz Raporu Alınması","soru":"Gömülü işletim sistemi için onaylanmış kod analiz raporu alınmakta mıdır?","oneri":"Gömülü işletim sistemi için mümkünse onaylanmış kod analiz raporu alınmalıdır.","kritiklik":3},{"id":80,"anaKat":"3.4. Nesnelerin İnterneti (IoT) Cihazlarının Güvenliği","altKat":"3.4.5. Diğer Güvenlik Tedbirleri","tedbirNo":"3.4.5.5","tedbir":"Tersine Mühendisliğe Karşı Koruma","soru":"Cihazın donanım ve yazılım bileşenleri tersine mühendisliği zorlaştıracak şekilde tasarlanmış mıdır?","oneri":"Cihazın donanımı ve yazılımı tersine mühendisliği zorlaştıracak şekilde tasarlanmış olmalı ve tersine mühendisliğe karşı korunmalıdır.","kritiklik":3},{"id":81,"anaKat":"3.5. Personel Güvenliği","altKat":"3.5.2. Eğitim ve Farkındalık Faaliyetleri","tedbirNo":"3.5.2.3","tedbir":"Yetenek İhtiyaç Analizi Yapılması","soru":"Bilgi güvenliği ve siber güvenlik alanında görev yapan personele yönelik yetenek ihtiyaç analizleri yapılmakta mıdır?","oneri":"Bilgi güvenliği ve siber güvenlik alanında görev yapan personel için yetenek ihtiyaç analizi yapılmalıdır. Yetenek ihtiyaç analizi çıktıları doğrultusunda eğitim yol haritası çıkarılmalı ve uygulamaya alınmalıdır.","kritiklik":2},{"id":82,"anaKat":"3.5. Personel Güvenliği","altKat":"3.5.3. Tedarikçi İlişkileri Güvenliği","tedbirNo":"3.5.3.10","tedbir":"Tedarik Zinciri İzleme Sürecinin Oluşturulması","soru":"Tedarik zinciri süresince, tedarik edilen hizmet/ürüne yönelik kritik bileşenlerin durumu izlenebilmekte midir?","oneri":"Yüklenici tarafından güvenlik gereksinimlerine uyumun garanti altına alınması amacıyla; tedarik zinciri süresince, tedarik edilen hizmet/ürüne yönelik kritik bileşenlerin durumunun izlenebilirliği sağlanmalıdır.","kritiklik":2},{"id":83,"anaKat":"3.5. Personel Güvenliği","altKat":"3.5.1. Genel Güvenlik Tedbirleri","tedbirNo":"3.5.1.1","tedbir":"Güvenlik Soruşturmalarının Yapılması","soru":"Doğrulama kontrolleri kapsamında adli sicil kaydı, geçmiş iş tecrübeleri ve ilişkili referansların kontrolü yapılmakta mıdır?","oneri":"İşe alım aşamasında, yasal düzenlemeler ve iş gereksinimleri göz önünde bulundurularak tüm aday personel için akademik bilgilerin ve geçmiş iş tecrübelerinin doğruluğu, referanslar ve sahip olunan sertifikaların geçerliliği kontrol edilmeli, adli sicil kaydı sorgulaması yapılmalıdır.","kritiklik":1},{"id":84,"anaKat":"3.5. Personel Güvenliği","altKat":"3.5.1. Genel Güvenlik Tedbirleri","tedbirNo":"3.5.1.2","tedbir":"Varlıkların Kabul Edilebilir Kullanım Kurallarının Tanımlanması","soru":"Varlıkların kabul edilebilir kullanım politikası belirlenmiş midir?","oneri":"Kurum varlıklarının kabul edilebilir kullanım politikası belirlenerek kurum personelinin ve yüklenicilerin bu kurallara uyum sağlaması taahhüt altına alınmalıdır.","kritiklik":1},{"id":85,"anaKat":"4.5. Kritik Altyapılar Güvenliği","altKat":"4.5.2. Enerji Sektörü Özelinde Güvenlik Tedbirleri","tedbirNo":"4.5.2.1","tedbir":"Cihaz Konfigürasyonları","soru":"EKS içerisinde yer alan tüm cihazların konfigürasyonları bilgi güvenliği gereksinimleri göz önünde bulundurularak yapılandırılmakta mıdır?","oneri":"EKS içerisinde yer alan hiçbir cihaz varsayılan ayarlarıyla sistem içerisinde konumlandırılmamalıdır. Cihaz konfigürasyonları bilgi güvenliği gereksinimlerine uygun olarak yapılmalıdır.","kritiklik":1},{"id":86,"anaKat":"4.5. Kritik Altyapılar Güvenliği","altKat":"4.5.2. Enerji Sektörü Özelinde Güvenlik Tedbirleri","tedbirNo":"4.5.2.2","tedbir":"Ağ Erişim Kontrolü","soru":"KBS ağı ve EKS ağı doğrudan iletişim kurmakta mıdır?","oneri":"EKS ağı ve kurumsal BT ağı arasındaki iletişimler için erişim kontrolü sağlanmalı ve yetkisiz erişimler engellenmelidir.","kritiklik":1},{"id":87,"anaKat":"4.5. Kritik Altyapılar Güvenliği","altKat":"4.5.2. Enerji Sektörü Özelinde Güvenlik Tedbirleri","tedbirNo":"4.5.2.3","tedbir":"Ağ Segmentasyonu","soru":"Operasyonel faaliyetler göz önünde bulundurularak EKS ağı segmentlere ayrılmış mıdır?","oneri":"Operasyonel faaliyetlerin kritikliği değerlendirilmeli ve EKS ağı belirlenen kritiklik derecesine göre segmentlere ayrılmalıdır. Oluşturulan ağlar birbirlerinden izole edilmeli ve erişim güvenliğine yönelik kısıtlayıcı önlemler alınmalıdır.","kritiklik":1},{"id":88,"anaKat":"5.2. Veri Tabanı Sıkılaştırma Tedbirleri","altKat":"5.2.1. Genel Sıkılaştırma Tedbirleri","tedbirNo":"5.2.1.21","tedbir":"Veri Tabanı Sunucusu ile İstemci Arasındaki İletişimin Şifreli Olması","soru":"Veri tabanı sunucusu ile istemci arasındaki iletişim şifreli trafik üzerinden mi sağlanmaktadır?","oneri":"Veri tabanı sunucusu ile istemci arasındaki iletişim şifreli trafik üzerinden sağlanmalıdır.","kritiklik":3},{"id":89,"anaKat":"5.2. Veri Tabanı Sıkılaştırma Tedbirleri","altKat":"5.2.1. Genel Sıkılaştırma Tedbirleri","tedbirNo":"5.2.1.16","tedbir":"Veri Tabanında Tablo ve Nesne Düzeyinde Yetkilendirme Yapılması","soru":"Kritik veri içeren tablo ve nesneler için tablo ve/veya nesne bazında yetkilendirme kullanılıyor mu?","oneri":"Kritik veri içeren tablo ve nesneler için tablo ve/veya nesne bazında yetkilendirme yapılmalıdır.","kritiklik":2},{"id":90,"anaKat":"5.2. Veri Tabanı Sıkılaştırma Tedbirleri","altKat":"5.2.1. Genel Sıkılaştırma Tedbirleri","tedbirNo":"5.2.1.17","tedbir":"İşletim Sistemi Üzerinde Veri Tabanı Servisi Çalıştıran Kullanıcıların Yönetici Haklarına Sahip Olmaması","soru":"İşletim sistemi üzerinde veri tabanı servis(ler)ini çalıştıran kullanıcılar için en az yetki prensibi uygulanmış mıdır?","oneri":"İşletim sistemi üzerinde veri tabanı servis(ler)ini çalıştıran kullanıcılar için en az yetki prensibi uygulanmalıdır. Bu kapsamda ilgili kullanıcılar, ihtiyaç duyulmadığı takdirde yönetici haklarına sahip olmamalıdır.","kritiklik":2},{"id":91,"anaKat":"4.3. Bulut Bilişim Güvenliği","altKat":"4.3.1. Genel Güvenlik Tedbirleri","tedbirNo":"4.3.1.14","tedbir":"Kaynakların Fiziksel Olarak İzole Edilmesi","soru":"Bulut sistemler üzerinde tutulan kuruma ait kritik verilerin kurum dışı başka varlıklar ile aynı fiziksel cihazda bulundurulmaması garanti altına alınmakta mıdır?","oneri":"Bulut sistemler üzerinde kuruma ait kritik veri bulundurulacaksa, kritik veriler kurum dışı başka kaynaklar ile aynı fiziksel cihaz üzerinde bulundurulmamalıdır.","kritiklik":3},{"id":92,"anaKat":"4.3. Bulut Bilişim Güvenliği","altKat":"4.3.1. Genel Güvenlik Tedbirleri","tedbirNo":"4.3.1.12","tedbir":"Güvenli Veri Depolama Politikasının Uygulanması","soru":"Bulut bilişim hizmet sağlayıcı tarafından güvenli veri depolama politikası hazırlanmış mıdır?","oneri":"Bulut bilişim hizmeti sunacak servis sağlayıcının veri güvenliğini (ifşa, değiştirme, bozulma vb. durumlara karşı) sağlamak adına güvenli veri depolama politikası bulunmalıdır.","kritiklik":2},{"id":93,"anaKat":"4.3. Bulut Bilişim Güvenliği","altKat":"4.3.1. Genel Güvenlik Tedbirleri","tedbirNo":"4.3.1.13","tedbir":"Bulut Ortamı İşlem Kayıtlarının Tutulması","soru":"Bulut sistemler üzerinde gerçekleştirilen işlemler kayıt altına alınmakta mıdır?","oneri":"Bulut sistemlerde gerçekleştirilen yönetimsel işlemler kayıt altına alınmalı ve değişmezliği sağlanmalıdır. Bk. Tedbir No: 3.1.8.1","kritiklik":2},{"id":94,"anaKat":"4.2. Anlık Mesajlaşma Güvenliği","altKat":"4.2.1. Genel Güvenlik Tedbirleri","tedbirNo":"4.2.1.8","tedbir":"Cihaz Üzerindeki Verinin Şifrelenmesi","soru":"Cihaz üzerinde tutulan veri şifreli olarak saklanmakta mıdır?","oneri":"Uygulama cihaz üzerinde sakladığı tüm veriyi şifreli olarak tutmalıdır.","kritiklik":3},{"id":95,"anaKat":"4.2. Anlık Mesajlaşma Güvenliği","altKat":"4.2.1. Genel Güvenlik Tedbirleri","tedbirNo":"4.2.1.9","tedbir":"Kritik Haberleşmenin Güvenliği","soru":"Kritik veri iletimini sağlayan uygulamanın yönetimi ve işletimi yerel olarak yapılmakta mıdır?","oneri":"Kritik veri içeren her türlü sesli, yazılı ve görüntülü haberleşme uygulamalarında, kaynak kodları kurum tarafından talep edildiğinde denetlenebilen, işletmesi ve yönetimi yerel olarak yapılabilen yerli ve milli uygulamalar tercih edilmelidir.","kritiklik":3},{"id":96,"anaKat":"4.6. Yeni Geliştirmeler ve Tedarik","altKat":"4.6.1. Genel Güvenlik Tedbirleri","tedbirNo":"4.6.1.5","tedbir":"Alt Yüklenici Yönetimi","soru":"Alt yüklenici ile çalışılma durumunda kurum tarafından işletilecek politika ve prosedürler tanımlanmış mıdır?","oneri":"Yeni geliştirmeler ve ürün/hizmet tedariki kapsamında alt yüklenici ile çalışılması durumunda işletilecek politika ve prosedürler tanımlanmış olmalıdır. Alt yüklenici tarafından gerçekleştirilecek değişiklik ve sürüm yönetimi faaliyetleri kurumun politika ve prosedürleri ile uyumlu olmalıdır.","kritiklik":2}];

